CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS compose_stacks(id INTEGER PRIMARY KEY,name TEXT NOT NULL,project_name TEXT NOT NULL UNIQUE,project_directory TEXT NOT NULL,compose_files TEXT NOT NULL,desired_state TEXT NOT NULL CHECK(desired_state IN('running','stopped')),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS git_repositories(id INTEGER PRIMARY KEY,stack_id INTEGER NOT NULL UNIQUE REFERENCES compose_stacks(id),name TEXT NOT NULL,url TEXT NOT NULL DEFAULT '',local_path TEXT NOT NULL,branch TEXT NOT NULL DEFAULT '',auth_ref TEXT NOT NULL DEFAULT 'host-ssh');
CREATE TABLE IF NOT EXISTS deployment_configs(stack_id INTEGER PRIMARY KEY REFERENCES compose_stacks(id),repository_id INTEGER NOT NULL REFERENCES git_repositories(id),polling_enabled INTEGER NOT NULL DEFAULT 0,poll_interval INTEGER NOT NULL DEFAULT 300,auto_deploy INTEGER NOT NULL DEFAULT 0,notify_on_failure INTEGER NOT NULL DEFAULT 1,no_cache INTEGER NOT NULL DEFAULT 0,build_pull INTEGER NOT NULL DEFAULT 0,pull_images INTEGER NOT NULL DEFAULT 1,remote_commit TEXT NOT NULL DEFAULT '',local_commit TEXT NOT NULL DEFAULT '',last_attempted_commit TEXT NOT NULL DEFAULT '',last_success_commit TEXT NOT NULL DEFAULT '',failure_count INTEGER NOT NULL DEFAULT 0,failed_commit TEXT NOT NULL DEFAULT '',retry_at INTEGER NOT NULL DEFAULT 0,next_poll_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY,stack_id INTEGER NOT NULL REFERENCES compose_stacks(id),task_type TEXT NOT NULL CHECK(task_type IN('git_check','git_pull','deploy','rebuild','start','stop','restart')),trigger_type TEXT NOT NULL CHECK(trigger_type IN('manual','scheduled')),service TEXT NOT NULL DEFAULT '',container_id TEXT NOT NULL DEFAULT '',start_after_deploy INTEGER NOT NULL DEFAULT 0,commit_sha TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('pending','running','success','failed','cancelled')),stage TEXT NOT NULL DEFAULT 'queued',exit_code INTEGER NOT NULL DEFAULT 0,log_path TEXT NOT NULL DEFAULT '',error_message TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),started_at TEXT NOT NULL DEFAULT '',finished_at TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS one_active_task_per_stack ON tasks(stack_id) WHERE status IN('pending','running');
CREATE INDEX IF NOT EXISTS tasks_status_id ON tasks(status,id);
CREATE TABLE IF NOT EXISTS app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credentials(name TEXT PRIMARY KEY,ciphertext TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_logs(id INTEGER PRIMARY KEY,task_id INTEGER REFERENCES tasks(id),stack_id INTEGER REFERENCES compose_stacks(id),recipient TEXT NOT NULL,notification_type TEXT NOT NULL,commit_sha TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,sent_at INTEGER NOT NULL,error_message TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS notification_dedup ON notification_logs(stack_id,commit_sha,stage,sent_at);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY,user TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
